export function localDate(now,tz='Asia/Dhaka'){return new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'}).format(now)}
export function dateAdd(date,n){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
export function required(e,date,kind,leaves=[],holidays=[]){if((!e.active&&!e.end_date)||date<e.join_date||(e.end_date&&date>e.end_date))return false;const day=new Date(date+'T12:00:00Z').getUTCDay();if(!(e.workdays||[1,2,3,4,5]).includes(day))return false;if(holidays.some(h=>h.work_date===date&&(!h.country||h.country===e.country)))return false;return !leaves.some(l=>l.employee_id===e.id&&l.status==='approved'&&l.start_date<=date&&l.end_date>=date&&(l.portion==='full'||(l.portion==='half'&&kind==='midday')))}
export function sessionSeconds(s,now=new Date()){if(!s)return 0;const end=new Date(s.ended_at||now).getTime(),start=new Date(s.started_at).getTime(),pause=s.paused_at?Math.max(0,(new Date(now)-new Date(s.paused_at))/1000):0;return Math.max(0,(end-start)/1000-Number(s.break_seconds||0)-pause)}
export function staleSession(s,now=new Date()){return !!s&&(s.needs_review||(!s.ended_at&&new Date(now)-new Date(s.started_at)>18*3600000))}
export function hoursLabel(s,now=new Date()){if(!s)return 'Not signed in';if(s.ended_at&&sessionSeconds(s,now)<28800)return s.needs_review?'Under 8h · Review':'Under 8 hours';if(staleSession(s,now))return 'Needs review';return sessionSeconds(s,now)>=28800?'8h reached':s.paused_at?'On break':'Working'}
export function status(e,date,kind,data,now=new Date()){if(!required(e,date,kind,data.leaves,data.holidays))return 'Exempt';if(data.updates.some(u=>u.employee_id===e.id&&u.work_date===date&&u.kind===kind))return 'Submitted';const ex=(data.exceptions||[]).find(x=>x.employee_id===e.id&&x.work_date===date);if(kind==='midday'&&ex){if(ex.status==='accepted')return 'Excused';if(ex.status==='pending')return 'Reason submitted'}const s=(data.sessions||[]).find(s=>s.employee_id===e.id&&s.work_date===date);if(!s)return 'Not signed in';if(staleSession(s,now))return 'Needs review';if(s.ended_at)return 'Missing';return sessionSeconds(s,now)>=(kind==='midday'?14400:26100)?'Due':'Pending'}
export function overall(a,b){const needed=[a,b].filter(x=>x!=='Exempt');if(!needed.length)return 'Exempt';if(needed.every(x=>['Submitted','Excused'].includes(x)))return needed.includes('Excused')?'Complete · Exception':'Complete';if(needed.includes('Reason submitted')||needed.includes('Needs review'))return 'Review needed';if(needed.includes('Submitted'))return 'Partial';if(needed.every(x=>x==='Pending'))return 'In progress';return 'No Update'}
export function csv(rows){return '\ufeff'+rows.map(row=>row.map(v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}).join(',')).join('\r\n')}
export function workDate(e,now=new Date()){return localDate(now,e.timezone)}
export function duration(seconds){const m=Math.floor(Math.max(0,seconds)/60);return `${Math.floor(m/60)}h ${String(m%60).padStart(2,'0')}m`}
export function hms(seconds){const s=Math.floor(Math.max(0,seconds));return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(x=>String(x).padStart(2,'0')).join(':')}
export function breakSeconds(s,now=new Date()){return !s?0:Number(s.break_seconds||0)+(s.paused_at?Math.max(0,(new Date(now)-new Date(s.paused_at))/1000):0)}
export function weekStart(date){const day=new Date(date+'T12:00:00Z').getUTCDay();return dateAdd(date,-((day+6)%7))}
export function reportBuckets(employees,data,from,to,now=new Date()){const buckets=new Map();for(const e of employees)for(let d=from;d<=to;d=dateAdd(d,1)){if(!required(e,d,'eod',data.leaves,data.holidays))continue;const key=e.id+weekStart(d);if(!buckets.has(key))buckets.set(key,{employee:e,week:weekStart(d),days:0,midRequired:0,eodRequired:0,seconds:0,breaks:0,extra:0,midday:0,eod:0,reason:0,excused:0,review:0,missing:0,hoursMet:0});const b=buckets.get(key),w=(data.sessions||[]).find(w=>w.employee_id===e.id&&w.work_date===d),a=status(e,d,'midday',data,now),z=status(e,d,'eod',data,now);b.days++;if(required(e,d,'midday',data.leaves,data.holidays))b.midRequired++;b.eodRequired++;b.seconds+=sessionSeconds(w,now);b.breaks+=breakSeconds(w,now);b.extra+=Math.max(0,sessionSeconds(w,now)-28800);if(a==='Submitted')b.midday++;if(z==='Submitted')b.eod++;if(a==='Reason submitted')b.reason++;if(a==='Excused')b.excused++;if(staleSession(w,now)||a==='Reason submitted')b.review++;if((a==='Missing'||a==='Due')||(z==='Missing'||z==='Due'))b.missing++;if(w&&!staleSession(w,now)&&sessionSeconds(w,now)>=28800)b.hoursMet++}return [...buckets.values()].sort((a,b)=>a.week.localeCompare(b.week)||a.employee.full_name.localeCompare(b.employee.full_name))}

export function zonedClock(at,zone){const d=new Date(at);return {time:new Intl.DateTimeFormat('en-US',{timeZone:zone,hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:true}).format(d),date:new Intl.DateTimeFormat('en-GB',{timeZone:zone,day:'2-digit',month:'short',year:'numeric'}).format(d),abbreviation:new Intl.DateTimeFormat('en-US',{timeZone:zone,timeZoneName:'short'}).formatToParts(d).find(p=>p.type==='timeZoneName').value}}
